/** Standalone representation IO comparison; not a journal or checkpoint reader. */
import {RootedJournalIO} from '../../utils/gradleOwnedStoreFs.js';
import {need} from '../../utils/gradleOwnedCurrentSchema.js';
import {canonicalOwnedJson} from '../../utils/gradleOwnedJson.js';
import {materializeS0c,expectedS0c,admitS0cCatalog,type Bundle,type Keys} from './gradleOwnedS0c.js';
export const objectName=(sha:string)=>'blob-'+sha+'.bin';
export async function persistS0c(io:RootedJournalIO,b:Bundle){for(const o of b.objects)await io.put(objectName(o.ref.sha256),o.bytes);}
export async function readS0cDisk(io:RootedJournalIO,catalog:Bundle,keys:Keys,gate:()=>void){const started=performance.now();gate();catalog=admitS0cCatalog(catalog);keys={...keys};const pin=expectedS0c(catalog);catalog={...catalog,profile:structuredClone(catalog.profile),roots:structuredClone(catalog.roots),retained:structuredClone(catalog.retained),objects:catalog.objects.map(o=>({ref:structuredClone(o.ref),bytes:Buffer.alloc(0)}))};gate();const before=await io.list(4096);gate();const expected=catalog.objects.map(o=>({name:objectName(o.ref.sha256),size:o.ref.byteLength})).sort((a,b)=>a.name<b.name?-1:1),normalize=(a:{name:string;size:number}[])=>a.sort((a,b)=>a.name<b.name?-1:1);need(canonicalOwnedJson(normalize(before))===canonicalOwnedJson(expected),'inventory_invalid');const objects=[];let freshBytes=0;for(const o of catalog.objects){gate();const bytes=await io.read(objectName(o.ref.sha256),o.ref.byteLength);gate();freshBytes+=bytes.length;objects.push({ref:o.ref,bytes});}const parseStarted=performance.now(),r=materializeS0c({...catalog,objects},keys,pin),materializeMs=performance.now()-parseStarted;gate();const after=await io.list(4096);gate();need(canonicalOwnedJson(normalize(after))===canonicalOwnedJson(expected),'inventory_invalid');return {...r,metrics:{...r.metrics,freshBytes,reads:objects.length,lists:2,materializeMs,wallMs:performance.now()-started,checkpointSyncIncluded:false}};}
